from .objects.integrity_objects import IntegrityCoreObjects
from interops.libraries.squish_actions import common
from interops.libraries.desktop import decorators as deco
from interops.libraries.squish_actions.constants import INTEGRITY_APP_NAME

def __get_integrity_menu_state() -> str:
    return common.get_objects_text_value(common.find_object(IntegrityCoreObjects.integrity_App_State_Label))

def __confirm_in_default_state() -> bool:
    state_label = __get_integrity_menu_state()

    if ("Logon" in state_label):
        return False
    return True

def __log_off_box_is_displayed() -> bool:
    return True if common.find_object(IntegrityCoreObjects.logOffDialog_Box_Label) is not None else False

@deco.set_separate_app_context(application_name=INTEGRITY_APP_NAME)
def click_log_off_button() -> None:
    if __confirm_in_default_state():
        common.left_click_object(IntegrityCoreObjects.menuBar_Logoff_Button)
        common.find_object(IntegrityCoreObjects.logOffDialog_Yes_Button)

@deco.set_separate_app_context(application_name=INTEGRITY_APP_NAME)
def click_yes_button_on_log_off_dialog() -> None:
    if __log_off_box_is_displayed():
        common.left_click_object(IntegrityCoreObjects.logOffDialog_Yes_Button)
        common.find_object(IntegrityCoreObjects.logOnBox_Pane)

@deco.set_separate_app_context(application_name=INTEGRITY_APP_NAME)
def click_no_button_on_log_off_dialog() -> None:
    if __log_off_box_is_displayed():
        common.left_click_object(IntegrityCoreObjects.logOffDialog_No_Button)
        common.find_object(IntegrityCoreObjects.logOnBox_Pane)

@deco.set_separate_app_context(application_name=INTEGRITY_APP_NAME)
def get_current_logged_in_username() -> str:
    if __confirm_in_default_state():
        return common.get_objects_text_value(IntegrityCoreObjects.integrity_Current_User_Label)
    raise RuntimeWarning("No user is currently logged in to Integrity")

@deco.set_separate_app_context(application_name=INTEGRITY_APP_NAME)
def is_user_already_logged_in(userName: str) -> bool:
    if __confirm_in_default_state():
        return True if common.get_objects_text_value(IntegrityCoreObjects.integrity_Current_User_Label).strip() == userName else False
    return False

